2	// One-shot seeder that imports the tag taxonomy from
3	// docs/tag_taxonomy_3_tiers.md.
4	//
5	// Tier rules:
6	//  - Tier 1 -> isAdult = false (safe, default-visible)
7	//  - Tier 2 -> isAdult = true  (gray-area / explicit mainstream)
8	//  - Tier 3 -> isAdult = true  (extreme / dead-dove)
9	//
10	// Run with:
11	//   npm run seed:tags
12	//
13	// The script is idempotent: it upserts on tag name (lower-cased),
14	// so re-running won't create duplicates and will update isAdult to
15	// match the taxonomy if it changed.
16	
17	import { existsSync, readFileSync } from 'node:fs';
18	import { resolve } from 'node:path';
19	import { PrismaClient } from '@prisma/client';
20	import { slugify } from '../src/common/utils/slug';
21	
22	const TAXONOMY_PATH = resolve(__dirname, '..', '..', 'docs', 'tag_taxonomy_3_tiers.md');
23	const EXTRAS_PATH = resolve(__dirname, '..', '..', 'docs', 'tag_extras.json');
24	
25	interface ParsedTag {
26	  name: string;
27	  isAdult: boolean;
28	}
29	
30	function parseTaxonomy(markdown: string): ParsedTag[] {
31	  const lines = markdown.split(/\r?\n/);
32	  const out: ParsedTag[] = [];
33	  const seen = new Set<string>();
34	
35	  let currentTier: 1 | 2 | 3 | null = null;
36	
37	  for (const raw of lines) {
38	    const tierMatch = raw.match(/^##\s+TIER\s+([123])\b/i);
39	    if (tierMatch) {
40	      currentTier = Number(tierMatch[1]) as 1 | 2 | 3;
41	      continue;
42	    }
43	
44	    if (currentTier === null) continue;
45	
46	    // Bullet item
47	    const bulletMatch = raw.match(/^\s*-\s+(.*)$/);
48	    if (!bulletMatch) continue;
49	
50	    let line = bulletMatch[1];
51	
52	    // Drop emojis (anything non-ASCII / non-whitespace) — keeps the
53	    // structure clean. Em-dashes stay because they're inside ASCII.
54	    line = line.replace(/[^\x00-\x7F]/g, '').trim();
55	    if (!line) continue;
56	
57	    // Drop parenthetical descriptions: "M/F (Het / Straight)" -> "M/F"
58	    line = line.replace(/\s*\([^)]*\)/g, '').trim();
59	    if (!line) continue;
60	
61	    // Drop trailing rating numbers like "/ 0", "/ 1", "/ 6+".
62	    line = line.replace(/\s*\/\s*\d+\+?\s*$/, '').trim();
63	
64	    // Heuristic: a long comma list ("CEO, Doctor, Nurse, ...") is
65	    // multiple tags. A short line ("Past Sexual Assault (off-page)")
66	    // is one tag with a comma in its description.
67	    let parts: string[];
68	    if ((line.match(/,/g) || []).length >= 3) {
69	      parts = line.split(/,/g).map((p) => p.trim());
70	    } else {
71	      parts = [line];
72	    }
73	
74	    for (let part of parts) {
75	      // Trailing punctuation cleanup
76	      part = part.replace(/[\s\-:]+$/, '').trim();
77	      if (!part) continue;
78	      // Skip pure-number "tags" (heat-rating remnants like "0", "1")
79	      if (/^\d+\+?$/.test(part)) continue;
80	
81	      const normalized = part.toLowerCase();
82	      if (seen.has(normalized)) continue;
83	      seen.add(normalized);
84	
85	      out.push({
86	        name: normalized,
87	        isAdult: currentTier !== 1,
88	      });
89	    }
90	  }
91	
92	  return out;
93	}
94	
95	function loadExtras(): ParsedTag[] {
96	  if (!existsSync(EXTRAS_PATH)) return [];
97	  const raw = readFileSync(EXTRAS_PATH, 'utf8');
98	  const arr = JSON.parse(raw) as { name: string; isAdult: boolean }[];
99	  return arr.map((t) => ({ name: t.name.toLowerCase(), isAdult: !!t.isAdult }));
100	}
101	
102	async function main() {
103	  const md = readFileSync(TAXONOMY_PATH, 'utf8');
104	  const parsed = parseTaxonomy(md);
105	  const extras = loadExtras();
106	
107	  // Extras may overlap the taxonomy — dedupe by name, last-write-wins so
108	  // the JSON file can override an isAdult flag on a taxonomy entry.
109	  const byName = new Map<string, ParsedTag>();
110	  for (const t of parsed) byName.set(t.name, t);
111	  for (const t of extras) byName.set(t.name, t);
112	  const all = Array.from(byName.values());
113	
114	  console.log(`Parsed ${parsed.length} tags from the taxonomy.`);
115	  if (extras.length > 0) {
116	    console.log(`Loaded ${extras.length} extras from docs/tag_extras.json.`);
117	  }
118	  const adult = all.filter((t) => t.isAdult).length;
119	  console.log(`  ${all.length - adult} safe, ${adult} adult, ${all.length} total.`);
120	
121	  const prisma = new PrismaClient();
122	  try {
123	    let created = 0;
124	    let updated = 0;
125	
126	    for (const tag of all) {
127	      const existing = await prisma.tag.findUnique({
128	        where: { name: tag.name },
129	      });
130	      if (!existing) {
131	        await prisma.tag.create({
132	          data: {
133	            name: tag.name,
134	            slug: await uniqueSlug(prisma, tag.name),
135	            isAdult: tag.isAdult,
136	          },
137	        });
138	        created++;
139	      } else if (existing.isAdult !== tag.isAdult) {
140	        await prisma.tag.update({
141	          where: { name: tag.name },
142	          data: { isAdult: tag.isAdult },
143	        });
144	        updated++;
145	      }
146	    }
147	
148	    console.log(`Created ${created} new tags, updated ${updated} existing tags.`);
149	  } finally {
150	    await prisma.$disconnect();
151	  }
152	}
153	
154	async function uniqueSlug(prisma: PrismaClient, name: string): Promise<string> {
155	  const base = slugify(name) || 'tag';
156	  let candidate = base;
157	  let n = 2;
158	  while (true) {
159	    const conflict = await prisma.tag.findUnique({
160	      where: { slug: candidate },
161	      select: { id: true },
162	    });
163	    if (!conflict) return candidate;
164	    candidate = `${base}-${n}`;
165	    n += 1;
166	  }
167	}
168	
169	main().catch((err) => {
170	  console.error(err);
171	  process.exit(1);
172	});
