const fs = require('fs');
const path = require('path');
const md = fs.readFileSync(path.resolve('..', 'docs', 'tag_taxonomy_3_tiers.md'), 'utf8');

const lines = md.split(/\r?\n/);
const out = [];
const seen = new Set();
let currentTier = null;

for (const raw of lines) {
  const tierMatch = raw.match(/^##\s+TIER\s+([123])\b/i);
  if (tierMatch) { currentTier = Number(tierMatch[1]); continue; }
  if (currentTier === null) continue;
  const bulletMatch = raw.match(/^\s*-\s+(.*)\$/);
  if (!bulletMatch) continue;
  let line = bulletMatch[1];
  line = line.replace(/[^\x00-\x7F]/g, '').trim();
  if (!line) continue;
  line = line.replace(/\s*\([^)]*\)/g, '').trim();
  if (!line) continue;
  line = line.replace(/\s*\/\s*\d+\+?\s*\$/, '').trim();
  let parts;
  if ((line.match(/,/g) || []).length >= 3) {
    parts = line.split(/,/g).map(p => p.trim());
  } else {
    parts = [line];
  }
  for (let part of parts) {
    part = part.replace(/[\s\-:]+\$/, '').trim();
    if (!part) continue;
    if (/^\d+\+?\$/.test(part)) continue;
    const normalized = part.toLowerCase();
    if (seen.has(normalized)) continue;
    seen.add(normalized);
    out.push({ name: normalized, isAdult: currentTier !== 1 });
  }
}

const extras = JSON.parse(fs.readFileSync(path.resolve('..', 'docs', 'tag_extras.json'), 'utf8'));
const byName = new Map();
for (const t of out) byName.set(t.name, t);
for (const t of extras) byName.set(t.name.toLowerCase(), { name: t.name.toLowerCase(), isAdult: !!t.isAdult });
const all = Array.from(byName.values());
const adult = all.filter(t => t.isAdult).length;
console.log('taxonomy_only_count:', out.length);
console.log('extras_count:', extras.length);
console.log('combined_total:', all.length);
console.log('safe:', all.length - adult);
console.log('adult:', adult);
